import React from 'react';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';

// #region Styled components
const StyledHeader = /* @__PURE__ */ styled.div({
  gridArea: 'header',
  width: '100%',
  padding: Spacings.Size8,
  boxSizing: 'border-box',
});
StyledHeader.displayName = 'Page.Header';
// #endregion

export interface HeaderProps
  extends WithChildren,
    Omit<React.HTMLAttributes<HTMLDivElement>, keyof StylingProps>,
    StylingProps,
    DataTestId {}

/** The `Header` component is used inside the `Page` component for displaying content at the very top of the page. */
export const Header = (props: HeaderProps) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  }: HeaderProps = props;

  return (
    <StyledHeader
      className={consumerClassName}
      style={consumerStyle}
      data-testid={dataTestId}
      {...remainingProps}
    >
      {children}
    </StyledHeader>
  );
};

Header.displayName = 'Page.Header';
